.category-border-amber { --cat: #c69139; border-left-color: #c69139 !important; }.category-border-sky { --cat: #5d9ab7; border-left-color: #5d9ab7 !important; }.category-border-violet { --cat: #8a6ca2; border-left-color: #8a6ca2 !important; }.category-border-emerald { --cat: #5e9077; border-left-color: #5e9077 !important; }.category-border-rose { --cat: #b66b79; border-left-color: #b66b79 !important; }.category-border-stone { --cat: #948d84; border-left-color: #948d84 !important; }

.shop-order-list { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; }
.order-card { position: relative; display: grid; align-content: start; gap: 5px; padding: 8px 9px; border: 1px solid var(--line-soft); border-left: 6px solid var(--cat, var(--line-soft)); border-radius: var(--radius-surface); background: var(--surface); cursor: pointer; }
.order-card:hover { border-color: var(--line); border-left-color: var(--cat, var(--line)); }
/* Stretched link: an invisible full-card anchor navigates to the order; the
   meta-row/foot's own controls (sheet stamp, preview) sit above it via z-index
   so they stay independently clickable. */
.order-card-link { position: absolute; inset: 0; z-index: 1; }
.order-card-meta-row a[href], .order-card-foot a[href], .order-preview-action { position: relative; z-index: 2; }
/* In selection mode the whole card toggles the pick — controls must not steal clicks. */
.selection-active .order-card-meta-row a[href], .selection-active .order-card-foot a[href], .selection-active .order-preview-action { pointer-events: none; }
.order-card-head { display: grid; gap: 1px; min-width: 0; }
.order-card-title { font-family: var(--font-mono); font-size: 0.8rem; font-weight: 700; line-height: 1.25; overflow-wrap: anywhere; }
/* Count and the отработка/cancelled stamp share this line, so a stamp never
   adds a row and grows the card. */
.order-card-meta-row { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
.order-card-count { display: inline-flex; align-items: baseline; gap: 4px; color: var(--ink-muted); font-size: 0.7rem; white-space: nowrap; }
.order-card-count strong { color: var(--ink); font-family: var(--font-mono); font-size: 0.92rem; font-weight: 700; }
.order-card-star { color: #c69139; font-size: 0.8rem; }
.order-card-foot { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding-top: 6px; border-top: 1px solid var(--line-soft); }
.order-card-meta { flex: 1 1 auto; min-width: 0; overflow: hidden; color: var(--ink-muted); font-size: 0.74rem; text-overflow: ellipsis; white-space: nowrap; }
.status-done { color: var(--success); background: var(--success-soft); }
.order-preview-action { display: inline-grid; width: 30px; height: 30px; min-height: 30px; padding: 0; border: 0; border-radius: var(--radius-control); color: var(--ink-soft); background: transparent; place-items: center; }
.order-preview-action .nav-ico { display: block; width: 18px; height: 18px; padding: 0; }
.order-preview-action:hover { color: var(--ink); background: var(--line-soft); }
.order-card.is-cancelled { opacity: 0.54; }
.order-card.is-cancelled .order-card-title { text-decoration: line-through; }
.order-card.is-cancelled { border-left-color: var(--ink-muted) !important; }
/* Inset, because an outline on a matrix card is clipped by the scroll container. */
/* Selection mode is unmistakable: every selectable card wears a checkbox, and
   picking one fills the box and rings the whole card in the accent colour —
   the category stripe included, so the outline stays square instead of lopsided. */
.selection-active .order-card { cursor: pointer; user-select: none; padding-right: 34px; transition: box-shadow 120ms ease, background 120ms ease; }
/* visibility, not display: none — keeps the count's box (and thus card height,
