.selection-active .order-card::after { position: absolute; top: 8px; right: 9px; display: grid; width: 20px; height: 20px; border: 2px solid var(--line); border-radius: 50%; background: var(--surface); color: transparent; content: "✓"; font-size: 0.68rem; font-weight: 700; line-height: 1; place-items: center; transition: background 120ms ease, border-color 120ms ease, color 120ms ease; }
.selection-active .order-card:hover::after { border-color: var(--crust); }
.order-card.is-selected { border-color: var(--crust) !important; box-shadow: inset 0 0 0 2px var(--crust); background: #f6e5db; }
.order-card.is-selected::after { border-color: var(--crust); background: var(--crust); color: #ffffff; }
.order-card.is-selected .order-card-star { display: none; }
.selection-active .order-card[data-cancelled="true"], .selection-active .order-card[data-sheet]:not([data-sheet=""]) { cursor: not-allowed; opacity: 0.45; }
.selection-active .order-card[data-cancelled="true"]::after, .selection-active .order-card[data-sheet]:not([data-sheet=""])::after { display: none; }
/* The toggle itself flips to an active look so the mode is obvious from the bar. */
[data-selection-toggle][aria-pressed="true"] { border-color: var(--crust); color: var(--crust-dark); background: #f6e5db; }
.sheet-olive { background-color: #e9eddc !important; }.sheet-copper { background-color: #f1e3d8 !important; }.sheet-blue { background-color: #e2eaf0 !important; }.sheet-plum { background-color: #ece2ec !important; }.sheet-moss { background-color: #e3ebe2 !important; }.sheet-clay { background-color: #eee2dc !important; }
.selection-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.table-hint { color: var(--ink-soft); font-size: 0.85rem; }
.window-nav { color: var(--ink-soft); font-size: 0.8rem; }
/* Pairs the view-switch with the date nav, and the category tabs with whatever
