.page-toolbar { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 10px; margin-bottom: 14px; }
.matrix-scroll, .summary-scroll, .journal-scroll, .item-table-wrap { overflow: auto; overscroll-behavior-inline: contain; }
/* Fade on the right edge of a table that can still be dragged sideways. It has
