.scroll-frame { position: relative; }
.scroll-frame::after { position: absolute; top: 0; right: 0; bottom: 0; width: 30px; background: linear-gradient(to left, rgba(20, 20, 19, 0.16), transparent); content: ""; opacity: 0; pointer-events: none; transition: opacity 140ms ease; }
.scroll-frame[data-scroll-more="true"]::after { opacity: 1; }
.order-matrix { width: 100%; min-width: 560px; border-collapse: separate; border-spacing: 0; table-layout: fixed; }
