.monitor-breakdown { margin-top: 14px; border-top: 1px solid var(--line); padding-top: 10px; }.monitor-breakdown > summary { cursor: pointer; font-weight: 700; }.monitor-breakdown section { margin-top: 12px; }.monitor-breakdown h3 { margin-bottom: 6px; }
.ingredient-list { display: grid; gap: 6px; margin: 8px 0 0; padding: 0; list-style: none; font-size: 0.8rem; }

.drafts-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; }
