.category-choice { display: flex; min-height: 64px; align-items: center; gap: 10px; padding: 10px 12px; border: 1px solid var(--line); border-radius: var(--radius-control); background: var(--surface); cursor: pointer; }
.category-choice:has(input:checked), .category-choice.is-selected { border-color: var(--ink); box-shadow: inset 0 0 0 1px var(--ink); }
.category-choice:has(input:focus-visible) { outline: 2px solid var(--focus); outline-offset: 2px; }
