.category-choice-amber .choice-letter { background: #a76b1f; }.category-choice-sky .choice-letter { background: #39718d; }.category-choice-violet .choice-letter { background: #74558b; }.category-choice-emerald .choice-letter { background: #477a62; }.category-choice-rose .choice-letter { background: #995565; }
.catalog-groups { display: grid; gap: 18px; }
