.sheet-view-input { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }
.sheet-switch { display: inline-flex; gap: 4px; margin-bottom: 16px; padding: 4px; border: 1px solid var(--line); border-radius: var(--radius-control); background: var(--paper-deep); }
.sheet-tab { padding: 7px 16px; border-radius: calc(var(--radius-control) - 4px); color: var(--ink-soft); font-weight: 700; cursor: pointer; }
#view-sheet:checked ~ .sheet-switch label[for="view-sheet"], #view-overview:checked ~ .sheet-switch label[for="view-overview"] { color: #ffffff; background: var(--crust); }
.sheet-view-input:focus-visible ~ .sheet-switch label[for="view-sheet"] { outline: 2px solid var(--crust); outline-offset: 2px; }
.sheet-panel { display: none; }
#view-sheet:checked ~ .sheet-panels .sheet-panel[data-panel="sheet"], #view-overview:checked ~ .sheet-panels .sheet-panel[data-panel="overview"] { display: block; }
/* «Обзор» pivot: the trailing/footer «Итого» stands out from the order columns. */
.overview-pivot { min-width: 0; }
.overview-pivot .overview-total-col { background: var(--paper-deep); }
.overview-pivot tfoot .overview-total-col { background: var(--surface-inset); }
.production-form .form-actions { justify-content: flex-end; margin-top: 16px; }
.dirty-warning { padding: 10px 12px; border: 1px solid; border-radius: var(--radius-control); font-size: 0.8rem; }
.batch-links { display: flex; flex-wrap: wrap; gap: 8px 14px; margin: -10px 0 22px; font-family: var(--font-mono); font-size: 0.78rem; }
.selection-orders { padding: 0; list-style: none; }
.selection-orders li { display: inline-flex; align-items: center; gap: 4px; }
.selection-orders .text-action { width: 44px; min-height: 44px; font-size: 1rem; }

.journal-table, .summary-table { border-collapse: separate; border-spacing: 0; }
/* Fixed layout: the date column gets one narrow, explicit width and every
   category column left unsized splits the rest evenly — no horizontal scroll. */
.journal-table { width: 100%; table-layout: fixed; }
.summary-table { width: 100%; min-width: 760px; }
.journal-table th, .journal-table td, .summary-table th, .summary-table td { padding: 8px; border-right: 1px solid var(--line-soft); border-bottom: 1px solid var(--line-soft); background: var(--surface); vertical-align: top; }
.summary-table th, .summary-table td { min-width: 126px; }
.journal-table thead th, .summary-table thead th { position: sticky; z-index: 20; top: 0; background: var(--paper-deep); text-align: center; }
.journal-table .journal-axis, .summary-table .summary-axis { position: sticky; z-index: 30; left: 0; background: var(--paper); text-align: left; }
.journal-table .journal-axis { width: 84px; }
.summary-table .summary-axis { min-width: 150px; max-width: 190px; }
.sheet-link { display: grid; gap: 8px; margin-bottom: 8px; padding: 12px; border: 0; border-radius: var(--radius-surface); color: var(--ink); text-decoration: none; }
.sheet-link:last-child { margin-bottom: 0; }
.sheet-link:hover { box-shadow: inset 0 0 0 1px var(--line); }
.sheet-link-head, .sheet-link-facts { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
.sheet-link-head strong { font-family: var(--font-mono); font-size: 0.92rem; }
.sheet-link-author { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.sheet-link-author, .sheet-link-facts { color: var(--ink-soft); font-size: 0.72rem; }
.category-tabs { display: flex; gap: 8px; overflow-x: auto; margin-bottom: 14px; padding: 3px; }
.category-tab { display: inline-flex; min-height: 44px; align-items: center; padding: 8px 12px; border-bottom: 2px solid transparent; color: var(--ink-soft); font-weight: 700; text-decoration: none; white-space: nowrap; }
.category-tab.is-active { border-color: currentColor; color: var(--ink); }
.view-switch { display: inline-flex; gap: 4px; padding: 4px; border: 1px solid var(--line); border-radius: var(--radius-control); background: var(--surface); }
.page-toolbar .category-tabs { margin-bottom: 0; }
.view-switch .view-tab { display: inline-flex; align-items: center; gap: 6px; padding: 7px 14px; border-radius: calc(var(--radius-control) - 4px); color: var(--ink-soft); font-weight: 700; text-decoration: none; }
.view-switch .view-tab .nav-ico { display: block; width: 20px; height: 20px; padding: 0; }
.view-switch .view-tab[aria-selected="true"] { color: #ffffff; background: var(--crust); }
.summary-table th a { display: grid; text-decoration: none; }
.summary-table thead small { font-weight: 400; }
.summary-table td { text-align: center; font-family: var(--font-mono); }
.summary-table tfoot th, .summary-table tfoot td { position: sticky; z-index: 20; bottom: 0; background: var(--paper-deep); font-weight: 800; }
.summary-table sup { margin-left: 3px; font-size: 0.65rem; }.negative { color: var(--danger); }.positive, .done { color: var(--success); }
.tone-today { box-shadow: inset 0 3px 0 var(--accent-teal); }.tone-tomorrow { box-shadow: inset 0 3px 0 var(--accent-amber); }

.calculator-catalog { max-height: 58vh; overflow-y: auto; }
.calculator-row { display: grid; grid-template-columns: minmax(0, 1fr) 92px; gap: 10px; align-items: center; min-height: 50px; border-bottom: 1px solid var(--line-soft); }
.calculator-row input { background: var(--surface); }

.admin-section { padding: 28px 0; border-top: 1px solid var(--line); }
.create-panel, .admin-row { border: 1px solid var(--line); border-radius: var(--radius-surface); background: var(--surface); }
.create-panel { margin-bottom: 24px; padding: 4px 16px 16px; }
.create-panel > summary, .admin-row > summary { min-height: 52px; padding: 14px 0; cursor: pointer; font-weight: 700; }
.admin-row { padding: 0 14px; }
.admin-row + .admin-row { margin-top: 8px; }
.admin-row > summary { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 12px; align-items: center; }
.admin-row > summary span:first-child { display: flex; align-items: center; gap: 12px; }
.admin-row > summary small { display: block; }
.admin-row form { margin: 8px 0 14px; }
.category-admin-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
.category-admin { padding: 16px; border: 1px solid var(--line); border-left: 4px solid var(--line); border-radius: var(--radius-surface); background: var(--surface); }
.category-admin h3 { margin-bottom: 12px; }
.available-list, .dish-admin-list, .admin-list { display: grid; gap: 8px; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
.user-table-wrap { overflow-x: auto; border: 1px solid var(--line); border-radius: var(--radius-surface); background: var(--surface); }
.user-table { width: 100%; border-collapse: collapse; }
.user-table th, .user-table td { padding: 12px 14px; border-bottom: 1px solid var(--line-soft); text-align: left; white-space: nowrap; }
.user-table tbody tr:last-child td { border-bottom: 0; }
.user-table thead th { color: var(--ink-muted); font-family: var(--font-mono); font-size: 0.68rem; text-transform: uppercase; letter-spacing: 0.02em; }
.user-table .col-actions { width: 1%; text-align: right; }
.user-edit { position: relative; display: inline-block; }
.user-edit > summary { list-style: none; }
.user-edit > summary::-webkit-details-marker { display: none; }
.user-edit-panel { position: absolute; z-index: 30; top: calc(100% + 6px); right: 0; display: grid; gap: 12px; width: min(280px, 78vw); padding: 16px; border: 1px solid var(--line); border-radius: var(--radius-surface); background: var(--surface); box-shadow: 0 8px 24px rgba(20, 20, 19, 0.14); text-align: left; white-space: normal; }
.user-edit-panel .stack { gap: 10px; }
.available-row { display: grid; grid-template-columns: minmax(160px, 1fr) 180px auto; gap: 10px; align-items: center; padding: 10px 0; border-bottom: 1px solid var(--line-soft); }
.reorder-actions { display: flex; gap: 6px; }
.catalog-tabs { display: grid; gap: 14px; }
.tab-bar { display: flex; flex-wrap: wrap; gap: 6px; padding: 4px; border: 1px solid var(--line); border-radius: var(--radius-control); background: var(--paper-deep); }
.tab-button { display: inline-flex; align-items: center; gap: 8px; min-height: 40px; padding: 6px 12px; border: 0; border-radius: calc(var(--radius-control) - 4px); color: var(--ink-soft); background: transparent; font-weight: 700; cursor: pointer; }
.tab-button[aria-selected="true"] { color: var(--ink); background: var(--surface); box-shadow: inset 0 0 0 1px var(--line); }
.tab-button:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
.tab-button .choice-letter { width: 24px; height: 24px; font-size: 0.85rem; }
.tab-count { display: inline-grid; min-width: 22px; height: 22px; place-items: center; padding: 0 6px; border-radius: 999px; background: var(--surface-inset); color: var(--ink-soft); font-size: 0.72rem; }
.empty-hint { padding: 12px; color: var(--ink-soft); font-size: 0.85rem; list-style: none; }
.tab-add { margin-left: auto; color: var(--ink-soft); }
.tab-sync { display: contents; }
.dish-adder { display: grid; gap: 10px; margin-bottom: 14px; }
.dish-adder .filters { margin: 0; padding: 0; border: 0; }
.category-settings { margin-bottom: 14px; border: 1px solid var(--line); border-radius: var(--radius-surface); background: var(--surface); }
.category-settings > summary { min-height: 48px; display: flex; align-items: center; padding: 0 14px; font-weight: 700; cursor: pointer; }
.category-settings > form { margin: 0; padding: 0 16px 16px; }
.dish-theme { margin-bottom: 18px; }
.theme-heading { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; font-size: 0.82rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.04em; color: var(--ink-soft); }
.dish-sortable { display: grid; gap: 8px; margin: 0; padding: 0; list-style: none; }
.sortable-item .admin-row > summary { grid-template-columns: auto minmax(0, 1fr) auto; }
.reorder-controls { display: inline-flex; gap: 4px; }
.reorder-controls .button-icon { width: 34px; min-height: 34px; }
.catalog-dialog { width: min(560px, calc(100% - 32px)); padding: 22px; border: 0; border-radius: var(--radius-surface); color: var(--ink); background: var(--surface); box-shadow: 0 8px 24px rgba(20, 20, 19, 0.12); }
.catalog-dialog::backdrop { background: var(--backdrop); }
.catalog-dialog h3 { margin-bottom: 14px; }
.techcard-ingredients { display: grid; gap: 4px; margin: 8px 0 14px; }
.techcard-ingredients li { display: flex; justify-content: space-between; gap: 12px; padding: 6px 0; border-bottom: 1px solid var(--line-soft); font-family: var(--font-mono); font-size: 0.85rem; }
.techcard-ingredients li:last-child { border: 0; }
.order-index { display: grid; min-width: 30px; height: 30px; place-items: center; border-radius: 50%; background: var(--paper-deep); font-family: var(--font-mono); font-size: 0.72rem; }
.profile-list { display: grid; margin: 24px 0; border-block: 1px solid var(--line); }
.profile-list div { display: grid; grid-template-columns: 160px 1fr; gap: 18px; padding: 14px 0; border-bottom: 1px solid var(--line-soft); }.profile-list div:last-child { border: 0; }.profile-list dt { color: var(--ink-muted); }.profile-list dd { margin: 0; font-weight: 700; }

.toast-region { position: fixed; z-index: 300; right: 16px; bottom: 16px; display: grid; gap: 8px; width: min(360px, calc(100% - 32px)); }
.toast { padding: 12px 14px; border: 1px solid var(--line); border-radius: var(--radius-control); color: var(--paper); background: var(--ink); }
.confirm-dialog { width: min(440px, calc(100% - 32px)); padding: 0; border: 0; border-radius: var(--radius-surface); color: var(--ink); background: var(--surface); box-shadow: 0 8px 24px rgba(20, 20, 19, 0.12); }
.confirm-dialog::backdrop { background: var(--backdrop); }
.confirm-dialog form { display: grid; gap: 18px; padding: 22px; }.confirm-dialog p { margin: 0; }.confirm-dialog menu { display: flex; justify-content: flex-end; gap: 8px; margin: 0; padding: 0; }
.preview-dialog { width: min(640px, calc(100% - 24px)); max-height: calc(100dvh - 40px); padding: 20px; overflow: auto; border: 0; border-radius: var(--radius-surface); color: var(--ink); background: var(--surface); box-shadow: 0 8px 24px rgba(20, 20, 19, 0.12); }
.preview-dialog::backdrop { background: var(--backdrop); }
.preview-header { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; }
.preview-meta { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin: 18px 0; }.preview-meta div { padding: 10px; background: var(--paper-deep); }.preview-meta dt { color: var(--ink-muted); font-size: 0.72rem; }.preview-meta dd { margin: 2px 0 0; font-weight: 700; }
.preview-items { display: grid; gap: 7px; max-height: 42vh; margin: 16px 0; padding: 0; overflow: auto; list-style: none; }.preview-items li { display: flex; justify-content: space-between; gap: 12px; padding-bottom: 7px; border-bottom: 1px solid var(--line-soft); }

@media (max-width: 900px) {
  :root { --bottom-bar: 62px; }
  /* Safety net: clip (not hidden) never makes a scroll container, so top-sticky
     headers and the tables' own overflow:auto scrollers keep working, but a
     stray over-wide element can't drag the whole page sideways. */
  html { overflow-x: clip; }
  /* Wordmark row is redundant once nav lives in the bottom bar — collapse the
     bar to nothing rather than display:none, which would also hide the
     fixed-positioned .main-nav still nested inside it. */
  .topbar { min-height: 0; padding: 0; border-bottom: 0; }
  .brand { display: none; }
  /* Nav leaves the header and becomes a fixed bottom tab bar in the thumb zone. */
  .main-nav { position: fixed; z-index: 90; right: 0; bottom: 0; left: 0; display: flex; justify-content: space-around; gap: 2px; margin: 0; padding: 6px 6px calc(6px + env(safe-area-inset-bottom)); border-top: 1px solid var(--line); background: var(--surface-veil); -webkit-backdrop-filter: blur(8px); backdrop-filter: blur(8px); }
  .main-nav a { flex: 1 1 0; display: flex; flex-direction: column; align-items: center; gap: 3px; min-width: 0; min-height: 52px; padding: 4px 2px; color: var(--ink-soft); font-size: 0.72rem; font-weight: 600; }
  .main-nav a::after { display: none; }
  .main-nav a[aria-current="page"] { color: var(--ink); }
  .nav-ico { display: block; }
  .main-nav a[aria-current="page"] .nav-ico { color: #ffffff; background: var(--crust); }
  .nav-label { max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  /* Clear the fixed bar. */
  .page { padding-bottom: calc(var(--bottom-bar) + env(safe-area-inset-bottom) + 24px); }
  .sticky-submit { bottom: calc(var(--bottom-bar) + env(safe-area-inset-bottom) + 8px); }
  .toast-region { bottom: calc(var(--bottom-bar) + env(safe-area-inset-bottom) + 12px); }
  /* minmax(0, …), not 1fr: plain 1fr floors the column at min-content, and the
     wide item/production tables inside would stretch the whole page instead of
     scrolling within their own wrapper. */
  .detail-grid, .production-layout, .calculator-layout { grid-template-columns: minmax(0, 1fr); }
  .detail-aside { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .monitor-panel { grid-column: 1 / -1; }
  .shop-order-list { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .drafts-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .category-admin-grid { grid-template-columns: 1fr; }
  .available-row { grid-template-columns: minmax(180px, 1fr) 1fr; }
  /* Tablet: shrink the day-label column so more days fit before it scrolls. */
  .order-matrix .matrix-axis { width: 78px; }
}

@media (max-width: 640px) {
  body { font-size: 15px; padding-bottom: env(safe-area-inset-bottom); }
  h1 { font-size: 2rem; }
  h2 { font-size: 1.42rem; }
  .page { padding: 22px 12px 52px; }
  .page-heading { display: grid; gap: 16px; margin-bottom: 20px; }
  .page-heading > .count { justify-self: start; }
  .page-heading .actions { width: 100%; }
  .page-heading .actions > * { flex: 1; }
  .button { min-height: 44px; }
  .surface { padding: 16px 12px; }
  .filters { display: grid; grid-template-columns: 1fr 1fr; padding-top: 8px; }
  .filters .field { grid-column: 1 / -1; }
  .field.compact { min-width: 0; }
  .form-grid.three { grid-template-columns: minmax(0, 1fr); }
  .login-page { grid-template-columns: 1fr; }
  .login-intro { min-height: 36vh; padding: 30px 22px; }
  .login-intro h1 { font-size: 4rem; }
  .login-form-wrap { align-items: start; padding: 28px 18px; }
  .brand small { display: none; }
  .window-nav { display: grid; grid-template-columns: auto 1fr auto; text-align: center; }
  .window-nav span { align-self: center; font-size: 0.7rem; }
  .order-matrix { min-width: 400px; }
  .order-matrix .matrix-axis { width: 60px; }
  .matrix-cell .order-card-title { overflow-wrap: normal; word-break: normal; }
  .matrix-cell .order-card-meta, .matrix-cell .order-preview-action { font-size: 0.68rem; }
  .shop-order-list { grid-template-columns: 1fr; }
  .drafts-grid { grid-template-columns: 1fr; }
  .meta-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .detail-aside { grid-template-columns: minmax(0, 1fr); }
  /* Quantities are the point of this page, so the table compresses to fit
     rather than hiding its numeric columns behind a horizontal scroll. */
  .item-table { min-width: 0; }
  .item-table th, .item-table td { padding: 8px 5px; }
  .category-picker, .category-picker.compact { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .category-choice { min-height: 58px; padding: 8px; }
  .catalog-row { grid-template-columns: minmax(130px, 1fr) 76px 76px; gap: 6px; }
  .catalog-row input { padding-inline: 4px; }
  .sticky-submit { right: 0; bottom: calc(var(--bottom-bar) + env(safe-area-inset-bottom)); left: 0; flex-wrap: wrap; justify-content: stretch; gap: 6px; padding: 8px; }
  /* min-width:0 + nowrap (from .button) let a box shrink past its own text,
     spilling the label outside the pill — three buttons (Отменить/Сохранить
     черновик/Создать заказ) never fit one row at phone width regardless.
     Give the primary action its own full row and let the rest share the row
     below evenly; wrap as a safety net if a label still doesn't fit. */
  .sticky-submit > * { flex: 1 1 0; min-width: 0; min-height: 38px; padding: 6px 8px; white-space: normal; text-align: center; }
  .sticky-submit > .button-primary { order: -1; flex-basis: 100%; }
  .journal-table .journal-axis { width: 60px; }
  .summary-table .summary-axis { min-width: 112px; max-width: 130px; }
  .summary-table th, .summary-table td, .journal-table th, .journal-table td { padding: 7px; }
  .summary-table th, .summary-table td { min-width: 104px; }
  .sheet-link-head { display: grid; gap: 2px; }
  .sheet-link-author { max-width: 18ch; }
  .sheet-link-facts { display: grid; justify-content: start; gap: 2px; }
  .calculator-catalog { max-height: none; }
  .admin-row > summary { grid-template-columns: 1fr; }
  .available-row { grid-template-columns: 1fr; }
  .profile-list div { grid-template-columns: 1fr; gap: 3px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; transition-duration: 0.01ms !important; animation-duration: 0.01ms !important; }
}

/* Dark appearance. Tokens are the single source of truth, so every component
   that uses var(--…) adapts automatically; the handful of light-tuned literal
   colors (category label text, journal row tints, selection washes) are
   re-mapped to dark equivalents below. All text pairs verified >= 4.5:1. */
@media (prefers-color-scheme: dark) {
  :root {
    color-scheme: dark;
    --paper: #191714;
    --paper-deep: #201d19;
    --surface: #24211c;
    --surface-inset: #2d2924;
    --ink: #f3efe8;
    --ink-soft: #cfcac1;
    --ink-muted: #9d978d;
    --ink-faint: rgba(207, 202, 193, 0.32);
    --crust: #dd8f5a;
    --line: #37332d;
    --line-soft: #302c27;
    --success: #8faa5e;
    --success-soft: #232a16;
    --warning: #d7a63f;
    --warning-soft: #322613;
    --danger: #e27070;
    --danger-soft: #331c1c;
    --focus: #dd8f5a;
    --surface-veil: rgba(26, 24, 20, 0.9);
    --backdrop: rgba(0, 0, 0, 0.55);
  }
  .category-amber { color: #d9a441; } .category-sky { color: #7bb4d0; } .category-violet { color: #b291c9; }
  .category-emerald { color: #6fbf95; } .category-rose { color: #d98a98; } .category-stone { color: #b3a89b; }
  .sheet-olive { background-color: #262a1c !important; } .sheet-copper { background-color: #2e241c !important; } .sheet-blue { background-color: #1e2733 !important; }
  .sheet-plum { background-color: #2b1f2b !important; } .sheet-moss { background-color: #1f291f !important; } .sheet-clay { background-color: #2c211b !important; }
  .order-card.is-selected { background: #3a2a22 !important; }
  [data-selection-toggle][aria-pressed="true"] { background: #3a2a22; }
}

