 .monitor-results { display: grid; gap: 10px; }
 .monitor-report { padding: 12px 0; border-top: 1px solid var(--line); }
 .monitor-total, .ingredient-list li { display: flex; justify-content: space-between; gap: 12px; }
 .monitor-total strong { font-family: var(--font-mono); font-size: 1.05rem; }
