{{define "order-form"}}
{{$data := .Data}}
{{$csrf := .CSRF}}
{{$update := eq $data.Mode "update"}}
{{$title := "Новая заявка"}}{{$step := "Тип заявки"}}{{$submit := "Создать заказ"}}
{{if $update}}{{$title = "Изменить заявку"}}{{$step = "Тип заявки (зафиксирован)"}}{{$submit = "Сохранить изменения"}}{{end}}
{{$back := "/orders"}}{{if $data.Order}}{{$back = printf "/orders/%s" (urlquery $data.Order.Number)}}{{end}}
<section class="page order-editor" data-order-editor>
  <header class="page-heading">
    {{template "page-title" (dict "Title" $title)}}
    <a class="button" href="{{$back}}" data-confirm="Уйти без сохранения? Введённые данные не сохранятся.">Закрыть</a>
  </header>
  <form class="editor-form" action="{{if $update}}/orders/{{urlquery $data.Order.Number}}/edit{{else}}/orders{{end}}" method="post" hx-disabled-elt="button[type=submit]" hx-sync="this:replace">
    {{template "csrf" $csrf}}
    <section class="editor-step">
      {{template "section-heading" (dict "Step" "1" "Title" $step)}}
      {{template "category-picker" (dict "Categories" $data.Categories "Selected" $data.CategoryID "Locked" $update)}}
    </section>
    <section class="editor-step">
      {{template "section-heading" (dict "Step" "2" "Title" "Куда и когда")}}
      <div class="form-grid two">
        {{if $data.WorkshopSource}}
          <label class="field"><span>Отправитель</span><input value="Цех Пекари" readonly></label>
        {{else}}
          <label class="field"><span>Отправитель</span><select name="from_department_id" required><option value="">Выберите отправителя</option>{{template "id-options" (dict "Items" $data.Shops "Selected" $data.FromDepartmentID)}}</select></label>
        {{end}}
        <label class="field"><span>Дата выполнения</span><input type="date" name="fulfillment_date" value="{{$data.FulfillmentDate}}" min="{{.Today}}" required></label>
      </div>
    </section>
    <section class="editor-step">
      <div class="section-heading"><div class="section-heading-main"><span class="step-number">3</span><h2>Позиции</h2></div><output class="editor-summary" data-editor-summary>0 поз.</output></div>
      <div class="catalog-groups">
      {{range $group := $data.Groups}}<section class="catalog-group"><h3>{{$group.Name}}</h3><div class="catalog-list">
        {{range $item := $group.Items}}<div class="catalog-row" data-catalog-row data-category="{{deref $item.Dish.CategoryID}}" data-name="{{$item.Dish.Name}}">
          <input type="hidden" name="item_name" value="{{$item.Dish.Name}}">
          <div class="catalog-name"><strong>{{$item.Dish.Name}}</strong><button class="text-action" type="button" data-comment-toggle>Комментарий</button></div>
          <label><span>Заявка</span><input class="quantity-input" type="number" name="quantity" min="0" step="1" inputmode="numeric" value="{{inputQty $item.Quantity}}"></label>
          <label><span>Заказ</span><input class="quantity-input" type="number" name="reserved_quantity" min="0" step="1" inputmode="numeric" value="{{inputQty $item.Reserved}}"></label>
          <label class="item-comment" hidden><span>Комментарий к позиции</span><input name="item_comment" value="{{$item.Comment}}" maxlength="500"></label>
        </div>{{end}}
      </div></section>{{end}}
      </div>
    </section>
    <section class="editor-step"><label class="field"><span>Общий комментарий</span><textarea name="general_comment" rows="3" maxlength="1000">{{$data.GeneralComment}}</textarea></label></section>
    <div class="sticky-submit">
      <a class="button" href="{{$back}}" data-confirm="Уйти без сохранения? Введённые данные не сохранятся.">Отменить</a>
      {{if and (not $update) (isShop .Viewer)}}<button class="button" type="submit" formaction="/orders/draft">Сохранить черновик</button>{{end}}
      <button class="button button-primary" type="submit">{{$submit}}</button>
    </div>
  </form>
</section>
{{end}}

@import url('https://fonts.googleapis.com/css2?family=Caprasimo:wght@400&family=Figtree:wght@400;600;700&display=swap');

:root {
  color-scheme: light;
  --paper: #f5ead8;
  --paper-deep: #ebddc5;
  --surface: #f9f4ed;
  --surface-inset: #eee7db;
  --ink: #201e1d;
  --ink-soft: #474238;
  --ink-muted: #82796a;
  --ink-faint: rgba(71, 66, 56, 0.38);
  --crust: #c67139;
  --crust-dark: #8c491a;
  --line: #dcd3c4;
  --line-soft: #eee7db;
  --success: #56633f;
  --success-soft: #f0fae1;
  --warning: #8a6412;
  --warning-soft: #f8edd2;
  --danger: #ad3838;
  --danger-soft: #f8e2df;
  --accent-teal: #8fa073;
  --accent-amber: #d67f48;
  --focus: #c67139;
  /* Translucent chrome (top bar, bottom nav, sticky footer) + modal scrim. */
  --surface-veil: rgba(249, 244, 237, 0.94);
  --backdrop: rgba(46, 43, 37, 0.5);
  --radius-control: 999px;
  --radius-surface: 20px;
  --max: 1180px;
  --font-serif: "Caprasimo", "Cormorant Garamond", Georgia, "Times New Roman", serif;
  --font-sans: Figtree, ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --font-mono: "JetBrains Mono", "SFMono-Regular", Consolas, "Liberation Mono", monospace;
}

* { box-sizing: border-box; }
[hidden] { display: none !important; }
html { min-width: 320px; background: var(--paper); scroll-padding-top: 76px; }
body { margin: 0; color: var(--ink); background: var(--paper); font-family: var(--font-sans); font-size: 15px; line-height: 1.55; letter-spacing: 0; }
button, input, select, textarea { font: inherit; letter-spacing: 0; }
button, a, input, select, textarea { touch-action: manipulation; }
a { color: inherit; text-underline-offset: 3px; }
button { cursor: pointer; }
button:disabled { cursor: not-allowed; opacity: 0.55; }
:where(button, a, input, select, textarea, summary):focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
h1, h2 { margin: 0; font-family: var(--font-serif); font-weight: 400; line-height: 1.08; letter-spacing: -0.02em; text-wrap: balance; }
h1 { font-size: 3.15rem; }
h2 { font-size: 1.65rem; }
h3 { margin: 0; font-size: 0.86rem; font-weight: 700; line-height: 1.3; }
p { text-wrap: pretty; }
small { display: block; color: var(--ink-muted); font-size: 0.78rem; }

.progress { position: fixed; z-index: 200; inset: 0 100% auto 0; height: 3px; background: var(--crust); opacity: 0; transition: inset 180ms ease, opacity 120ms ease; }
.progress.htmx-request { inset-right: 18%; opacity: 1; }
.htmx-request .progress { inset-right: 18%; opacity: 1; }
.app-shell { min-height: 100dvh; }
.topbar { display: flex; align-items: center; gap: 32px; min-height: 68px; padding: 10px max(20px, calc((100vw - var(--max)) / 2)); border-bottom: 1px solid var(--line-soft); background: var(--surface-veil); }
.brand { display: inline-flex; align-items: center; gap: 10px; min-width: max-content; color: var(--ink); text-decoration: none; }
.brand strong { display: block; font-family: var(--font-serif); font-size: 1.1rem; font-weight: 600; line-height: 1.05; }
.brand small { font-size: 0.66rem; }
.main-nav { display: flex; align-items: center; gap: 22px; margin-left: auto; }
.main-nav a { position: relative; min-height: 44px; padding: 12px 0 10px; color: var(--ink-soft); font-size: 0.88rem; font-weight: 600; text-decoration: none; white-space: nowrap; }
.main-nav a::after { position: absolute; right: 0; bottom: 5px; left: 0; height: 2px; background: var(--crust); content: ""; opacity: 0; transform: scaleX(0); transition: opacity 140ms ease, transform 140ms ease; }
.main-nav a:hover::after, .main-nav a[aria-current="page"]::after { opacity: 1; transform: scaleX(1); }
.main-nav a[aria-current="page"] { color: var(--ink); }
.nav-sprite { position: absolute; width: 0; height: 0; overflow: hidden; }
/* Shown only in the mobile bottom bar; desktop nav is text-only. box-sizing so
   the padding insets the 24-viewBox glyph inside the active pill. */
.nav-ico { display: none; box-sizing: border-box; width: 44px; height: 30px; padding: 4px 11px; border-radius: 9px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.nav-label { line-height: 1; }

.page { width: min(100%, calc(var(--max) + 40px)); margin: 0 auto; padding: 32px 20px 64px; }
.narrow-page { width: min(100%, 720px); }
.page-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 28px; margin-bottom: 28px; }
.page-heading .lede { max-width: 640px; margin: 8px 0 0; color: var(--ink-soft); }
.eyebrow { margin: 0 0 4px; color: var(--ink-muted); font-family: var(--font-mono); font-size: 0.71rem; font-weight: 700; letter-spacing: 0.02em; text-transform: uppercase; }
.actions, .form-actions, .window-nav, .heading-badges { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.count { display: inline-grid; min-width: 30px; height: 30px; padding: 0 8px; place-items: center; border: 1px solid var(--line); border-radius: 50%; color: var(--ink-soft); font-family: var(--font-mono); font-size: 0.78rem; }
.section-heading { display: flex; align-items: center; justify-content: space-between; gap: 16px; margin-bottom: 18px; }
/* Keeps the step number next to its title; space-between used to fling them apart. */
.section-heading-main { display: flex; align-items: center; gap: 12px; }
.section-heading h2 { font-size: 1.45rem; }

.button { display: inline-flex; min-height: 42px; align-items: center; justify-content: center; gap: 7px; padding: 8px 15px; border: 1px solid var(--line); border-radius: var(--radius-control); color: var(--ink); background: transparent; font-weight: 650; line-height: 1.2; text-align: center; text-decoration: none; white-space: nowrap; transition: background 130ms ease, border-color 130ms ease; }
.button:hover { border-color: rgba(20, 20, 19, 0.3); background: var(--paper-deep); }
.button-primary { border-color: var(--crust-dark); color: #ffffff; background: var(--crust-dark); }
.button-primary:hover { border-color: var(--crust-dark); background: var(--crust-dark); }
.button-danger { border-color: rgba(198, 69, 69, 0.38); color: var(--danger); }
.button-danger:hover { background: var(--danger-soft); }
.button-ghost { border-color: transparent; }
.button-wide { width: 100%; }
.button-icon { width: 44px; padding: 0; font-size: 1.1rem; }
.text-action { min-height: 32px; padding: 0; border: 0; color: var(--ink-soft); background: transparent; font-size: 0.75rem; text-decoration: underline; }

.flash { width: min(calc(100% - 40px), var(--max)); margin: 16px auto 0; padding: 11px 14px; border: 1px solid var(--line); border-radius: var(--radius-control); display: flex; align-items: flex-start; gap: 8px; }
.flash::before { flex: none; width: 1em; font-weight: 700; font-size: 1em; line-height: inherit; text-align: center; }
.flash-error { border-color: rgba(198, 69, 69, 0.3); color: var(--danger); background: var(--danger-soft); }
.flash-error::before { content: "\2715\FE0E"; }
.flash-success { border-color: rgba(93, 184, 114, 0.3); color: var(--success); background: var(--success-soft); }
.flash-success::before { content: "\2713\FE0E"; }
.flash-warning, .dirty-warning { border-color: rgba(212, 160, 23, 0.28); color: var(--warning); background: var(--warning-soft); }
.flash-warning::before, .dirty-warning::before { content: "\26A0\FE0E"; }
.surface { padding: 24px; border-radius: var(--radius-surface); background: var(--paper-deep); }
.muted, .form-note { color: var(--ink-muted); }
.empty-state { padding: 48px 24px; border: 1px dashed var(--line); border-radius: var(--radius-surface); color: var(--ink-soft); text-align: center; }
.empty-state.compact { padding: 24px 16px; }
.empty-cell { display: block; color: var(--ink-faint); text-align: center; }

.field { display: grid; gap: 6px; min-width: 0; }
.field > span, .catalog-row label > span { color: var(--ink-soft); font-size: 0.78rem; font-weight: 650; }
.field.compact { min-width: 180px; }
input, select, textarea { width: 100%; min-height: 44px; border: 1px solid var(--line); border-radius: var(--radius-control); color: var(--ink); background: var(--surface-inset); padding: 9px 12px; font-size: 16px; }
/* Dense numeric grids (order/production/calculator quantity boxes) stay a
   rounded rect, not a full pill — a stadium shape reads badly at 56-92px wide. */
.quantity-input { border-radius: 14px; }
textarea { resize: vertical; }
input::placeholder, textarea::placeholder { color: var(--ink-muted); }
.form-grid { display: grid; gap: 14px; }
.form-grid.two { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.form-grid.three { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.field-wide { grid-column: 1 / -1; }
.action-field { justify-content: end; }
.filters { display: flex; flex-wrap: wrap; align-items: end; gap: 12px; margin-bottom: 24px; padding: 16px 0; border-block: 1px solid var(--line-soft); }
.search-field { max-width: 420px; margin-bottom: 16px; }

.login-page { display: grid; min-height: 100dvh; grid-template-columns: minmax(0, 1.15fr) minmax(340px, 0.85fr); }
.login-intro { display: flex; flex-direction: column; justify-content: flex-end; padding: clamp(36px, 7vw, 96px); color: var(--surface); background: var(--ink); }
.login-intro h1 { font-size: 7rem; }
.login-intro p:last-child { max-width: 540px; margin: 20px 0 0; color: #a09d96; font-size: 1.1rem; }
.login-form-wrap { display: grid; place-items: center; padding: 28px; }
.login-form-wrap form { width: min(100%, 390px); }
.stack { display: grid; gap: 18px; }

.category { display: inline-flex; align-items: center; gap: 6px; color: var(--ink-soft); font-size: 0.75rem; font-weight: 700; }
.category > span { width: 8px; height: 8px; border-radius: 50%; background: currentColor; }
.category-amber { color: #8a5a16; }.category-sky { color: #32657f; }.category-violet { color: #6e4f86; }.category-emerald { color: #3e6e58; }.category-rose { color: #914f5d; }.category-stone { color: #716a61; }
.category-border-amber { --cat: #c69139; border-left-color: #c69139 !important; }.category-border-sky { --cat: #5d9ab7; border-left-color: #5d9ab7 !important; }.category-border-violet { --cat: #8a6ca2; border-left-color: #8a6ca2 !important; }.category-border-emerald { --cat: #5e9077; border-left-color: #5e9077 !important; }.category-border-rose { --cat: #b66b79; border-left-color: #b66b79 !important; }.category-border-stone { --cat: #948d84; border-left-color: #948d84 !important; }

.shop-order-list { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; }
.order-card { position: relative; display: grid; align-content: start; gap: 5px; padding: 8px 9px; border: 1px solid var(--line-soft); border-left: 6px solid var(--cat, var(--line-soft)); border-radius: var(--radius-surface); background: var(--surface); cursor: pointer; }
.order-card:hover { border-color: var(--line); border-left-color: var(--cat, var(--line)); }
/* Stretched link: an invisible full-card anchor navigates to the order; the
   meta-row/foot's own controls (sheet stamp, preview) sit above it via z-index
   so they stay independently clickable. */
.order-card-link { position: absolute; inset: 0; z-index: 1; }
.order-card-meta-row a[href], .order-card-foot a[href], .order-preview-action { position: relative; z-index: 2; }
/* In selection mode the whole card toggles the pick — controls must not steal clicks. */
.selection-active .order-card-meta-row a[href], .selection-active .order-card-foot a[href], .selection-active .order-preview-action { pointer-events: none; }
.order-card-head { display: grid; gap: 1px; min-width: 0; }
.order-card-title { font-family: var(--font-mono); font-size: 0.8rem; font-weight: 700; line-height: 1.25; overflow-wrap: anywhere; }
/* Count and the отработка/cancelled stamp share this line, so a stamp never
   adds a row and grows the card. */
.order-card-meta-row { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
.order-card-count { display: inline-flex; align-items: baseline; gap: 4px; color: var(--ink-muted); font-size: 0.7rem; white-space: nowrap; }
.order-card-count strong { color: var(--ink); font-family: var(--font-mono); font-size: 0.92rem; font-weight: 700; }
.order-card-star { color: #c69139; font-size: 0.8rem; }
.order-card-foot { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding-top: 6px; border-top: 1px solid var(--line-soft); }
.order-card-meta { flex: 1 1 auto; min-width: 0; overflow: hidden; color: var(--ink-muted); font-size: 0.74rem; text-overflow: ellipsis; white-space: nowrap; }
